-- H2-compatible DDL for the expert_reviews table. -- Mirrors V20__create_expert_reviews.sql. -- -- Differences from PostgreSQL: --   * No FK to users or safety_events (matches the H2 mirror pattern --     used by schema-safety-events.sql: app-layer service enforces --     the linkage; production schema keeps the FKs). --   * TEXT maps to CLOB in H2. --   * TIMESTAMPTZ maps to TIMESTAMP.  CREATE TABLE IF NOT EXISTS expert_reviews (     id              UUID         NOT NULL PRIMARY KEY,     safety_event_id UUID         NOT NULL,     reviewer_id     UUID         NOT NULL,     decision        VARCHAR(30)  NOT NULL,     note            CLOB         NULL,     created_at      TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,      CONSTRAINT expert_reviews_event_reviewer_uq         UNIQUE (safety_event_id, reviewer_id),      CONSTRAINT expert_reviews_decision_chk         CHECK (decision IN (             'CONFIRM_RISK',             'DOWNGRADE_RISK',             'ESCALATE',             'NO_ACTION',             'CONTINUE_MONITORING',             'REQUEST_FOLLOWUP',             'DISMISS'         )) );  CREATE INDEX IF NOT EXISTS expert_reviews_event_idx     ON expert_reviews (safety_event_id);  CREATE INDEX IF NOT EXISTS expert_reviews_reviewer_idx     ON expert_reviews (reviewer_id);  CREATE INDEX IF NOT EXISTS expert_reviews_created_at_idx     ON expert_reviews (created_at);